package dev.eugheist.ttmodern;
final class DeviceTooltipAudit {
 static void key(net.minecraft.network.chat.Component line,String expected){if(!(line.getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents content)||!content.getKey().equals("ttwaila."+expected))throw new IllegalStateException("Device tooltip key "+expected);}
 static void run(net.minecraft.server.MinecraftServer server){
  var world=server.overworld();var pos=new net.minecraft.core.BlockPos(12,310,18);var other=pos.east();var originals=new java.util.LinkedHashMap<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState>();var data=new java.util.HashMap<net.minecraft.core.BlockPos,net.minecraft.nbt.CompoundTag>();
  for(var at:java.util.List.of(pos,other)){originals.put(at,world.getBlockState(at));var tile=world.getBlockEntity(at);if(tile!=null)data.put(at,tile.saveWithFullMetadata(world.registryAccess()));}
  try{
   world.setBlock(pos,ThaumicTinkererModern.ANIMATION_TABLET.get().defaultBlockState(),3);var tablet=(AnimationTabletEntity)world.getBlockEntity(pos);key(DeviceTooltip.lines(tablet).getFirst(),"currentTool");if(DeviceTooltip.lines(tablet).size()!=1)throw new IllegalStateException("Empty tablet extra modes");tablet.inventory.setStackInSlot(0,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND_PICKAXE));
   for(boolean left:new boolean[]{false,true})for(boolean redstone:new boolean[]{false,true}){tablet.leftClick=left;tablet.redstone=redstone;var before=tablet.saveWithoutMetadata(world.registryAccess());var lines=DeviceTooltip.lines(tablet);if(net.neoforged.fml.ModList.get().isLoaded("jade"))JadePlugin.audit(world,tablet);key(lines.get(1),left?"leftClick":"rightClick");key(lines.get(2),redstone?"redstone":"autonomous");if(!before.equals(tablet.saveWithoutMetadata(world.registryAccess())))throw new IllegalStateException("Tooltip mutated tablet");}
   world.removeBlockEntity(pos);world.setBlock(pos,ThaumicTinkererModern.MOB_MAGNET.get().defaultBlockState(),3);var magnet=(MagnetEntity)world.getBlockEntity(pos);
   for(boolean pulling:new boolean[]{false,true})for(boolean adult:new boolean[]{false,true})for(boolean filtered:new boolean[]{false,true}){world.setBlock(pos,magnet.getBlockState().setValue(MagnetBlock.PULLING,pulling),3);magnet.adult=adult;var mould=new net.minecraft.world.item.ItemStack(ThaumicTinkererModern.SOUL_MOULD.get());net.minecraft.world.item.component.CustomData.update(net.minecraft.core.component.DataComponents.CUSTOM_DATA,mould,t->t.putString("pattern","minecraft:cow"));magnet.inventory.setStackInSlot(0,filtered?mould:net.minecraft.world.item.ItemStack.EMPTY);var lines=DeviceTooltip.lines(magnet);key(lines.get(0),pulling?"pullingMode":"pushingMode");key(lines.get(1),(pulling?"pulling":"pushing")+(adult?"Adult":"Child")+(filtered?"Type":""));}
   world.removeBlockEntity(pos);world.setBlock(pos,ThaumicTinkererModern.REPAIRER.get().defaultBlockState(),3);var repairer=(RepairerEntity)world.getBlockEntity(pos);if(!DeviceTooltip.lines(repairer).isEmpty())throw new IllegalStateException("Empty repairer tooltip");var pick=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND_PICKAXE);repairer.inventory.setStackInSlot(0,pick);key(DeviceTooltip.lines(repairer).getFirst(),"finishedRepairing");pick.setDamageValue(13);key(DeviceTooltip.lines(repairer).getFirst(),"repairing");
   world.removeBlockEntity(pos);world.setBlock(pos,ThaumicTinkererModern.INTERFACE.get().defaultBlockState(),3);var link=(TransvectorEntity)world.getBlockEntity(pos);if(DeviceTooltip.lines(link).size()!=1)throw new IllegalStateException("Unbound interface coordinates");world.setBlock(other,net.minecraft.world.level.block.Blocks.CHEST.defaultBlockState(),3);link.link(other);var lines=DeviceTooltip.lines(link);key(lines.getFirst(),"connected");if(lines.size()!=2||!lines.get(1).getString().equals("x: 13 y: 310 z: 18"))throw new IllegalStateException("Interface target coordinates");world.removeBlockEntity(other);world.setBlock(other,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);if(DeviceTooltip.lines(link).size()!=1)throw new IllegalStateException("Missing target stale coordinates");
   if(KamiStartupConfig.enabled()){var gate=new WarpGateEntity(pos,WarpGateBlock.BLOCK.get().defaultBlockState());gate.locked=false;key(DeviceTooltip.lines(gate).getFirst(),"allowIncoming");gate.locked=true;key(DeviceTooltip.lines(gate).getFirst(),"disallowIncoming");}
   if(net.neoforged.fml.ModList.get().isLoaded("jade"))System.out.println("TT JADE PAYLOAD AUDIT: ALL PASS (real plugin discovery,server provider,localized component codec,other provider data preserved)");
   System.out.println("TT DEVICE TOOLTIP AUDIT: ALL PASS (empty/equipped tablet,modes,eight mob filter/age/polarity combinations,repair state,live/missing interface,gate lock semantics,read-only)");
  }finally{for(var at:originals.keySet()){world.removeBlockEntity(at);world.setBlock(at,originals.get(at),3);var tile=world.getBlockEntity(at);if(tile!=null&&data.containsKey(at))tile.loadWithComponents(data.get(at),world.registryAccess());}}
 }
}
